//! The Library: the font set and the asset map a graphic draws with, built
//! from bytes the caller read (G-2, G-6 — never `load_system_fonts`), its
//! content version, the `measure_text` memo, and the usvg options every
//! parse shares, whose resolvers record what resvg itself never reports.
//! The generic families `serif`, `sans-serif` and `monospace` are named on
//! the database (G-6), and a font is chosen from the text's OWN families
//! only, never usvg's appended `serif` fallback.

use std::collections::{BTreeMap, HashMap};
use std::sync::{Arc, Mutex, MutexGuard};

use resvg::usvg;
use resvg::usvg::fontdb;
use sha2::{Digest, Sha256};

use crate::diagnostic::Diagnostic;
use crate::images::{cached_kind, Asset};
use crate::measure::{FontStyle, TextMetrics};

/// `(family, size bits, weight, style, letter-spacing bits, preserve, text)`.
pub(crate) type MemoKey = (String, u64, u16, FontStyle, u64, bool, String);

/// The memo is cleared when it reaches this many entries.
const MEMO_CAP: usize = 4096;

/// The engine's fonts and assets. Immutable once built; `Send + Sync`.
pub struct Library {
    db: Arc<fontdb::Database>,
    assets: BTreeMap<String, Asset>,
    families: Vec<String>,
    version: String,
    warnings: Vec<Diagnostic>,
    memo: Mutex<HashMap<MemoKey, TextMetrics>>,
}

/// One loaded face.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Face {
    pub family: String,
    pub post_script_name: String,
    pub weight: u16,
    pub italic: bool,
}

/// What one parse's resolvers saw: the family lists no face answered, the
/// hrefs that name no asset, whether a data: URL was met, and the assets
/// that are not images.
#[derive(Default)]
pub(crate) struct Probe {
    pub(crate) families: Vec<Vec<usvg::FontFamily>>,
    pub(crate) hrefs: Vec<String>,
    pub(crate) data_url: bool,
    pub(crate) bad_assets: Vec<String>,
}

/// Every closure takes the lock only for its own push: a nested SVG asset
/// re-enters `select_font` on the same thread, and the lock is not
/// re-entrant.
pub(crate) fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

impl Library {
    pub fn new(fonts: Vec<Vec<u8>>, assets: BTreeMap<String, Vec<u8>>) -> Library {
        let version = version_of(&fonts, &assets);
        let mut db = fontdb::Database::new();
        let mut warnings = Vec::new();
        for (index, bytes) in fonts.into_iter().enumerate() {
            let before = db.len();
            db.load_font_data(bytes);
            if db.len() == before {
                warnings.push(Diagnostic::warning(format!("font {index} loaded no face")));
            }
        }
        // G-6's generics; `cursive` and `fantasy` keep fontdb's defaults,
        // which the set lacks, so they are warned like any missing family.
        db.set_serif_family("Source Serif 4");
        db.set_sans_serif_family("Source Sans 3");
        db.set_monospace_family("IBM Plex Mono");
        let mut families: Vec<String> = db
            .faces()
            .filter_map(|face| face.families.first().map(|(name, _)| name.clone()))
            .collect();
        families.sort();
        families.dedup();
        Library {
            db: Arc::new(db),
            assets: assets
                .into_iter()
                .map(|(name, data)| {
                    let digest = Sha256::digest(&data).into();
                    let data = Arc::new(data);
                    (name, Asset { data, digest })
                })
                .collect(),
            families,
            version,
            warnings,
            memo: Mutex::new(HashMap::new()),
        }
    }

    /// Primary family names, sorted and deduplicated.
    pub fn families(&self) -> &[String] {
        &self.families
    }

    pub fn faces(&self) -> Vec<Face> {
        self.db
            .faces()
            .map(|face| Face {
                family: face
                    .families
                    .first()
                    .map(|(name, _)| name.clone())
                    .unwrap_or_default(),
                post_script_name: face.post_script_name.clone(),
                weight: face.weight.0,
                italic: face.style != fontdb::Style::Normal,
            })
            .collect()
    }

    pub fn asset_names(&self) -> Vec<&str> {
        self.assets.keys().map(String::as_str).collect()
    }

    pub fn asset(&self, name: &str) -> Option<&[u8]> {
        self.assets.get(name).map(|asset| asset.data.as_slice())
    }

    /// SHA-256 of the font and asset bytes, 64 lowercase hex characters.
    pub fn version(&self) -> &str {
        &self.version
    }

    /// One per font blob that loaded no face.
    pub fn warnings(&self) -> &[Diagnostic] {
        &self.warnings
    }

    pub(crate) fn memo_get(&self, key: &MemoKey) -> Option<TextMetrics> {
        lock(&self.memo).get(key).copied()
    }

    pub(crate) fn memo_put(&self, key: MemoKey, metrics: TextMetrics) {
        let mut memo = lock(&self.memo);
        if memo.len() >= MEMO_CAP {
            memo.clear();
        }
        memo.insert(key, metrics);
    }

    /// The options every parse uses: this font set only, `<image>` hrefs
    /// answered from the asset map only, and every miss recorded in
    /// `probe`. `Options` is not `Clone`, so each call builds its own.
    pub(crate) fn options<'a>(&'a self, probe: &'a Mutex<Probe>) -> usvg::Options<'a> {
        let select_font: usvg::FontSelectionFn<'a> = Box::new(move |font, db| {
//! `rasterize`: usvg parse with the Library's options → resvg render → the
//! RGBA→BGRA swizzle into the caller's strided buffer (G-7), and the
//! warnings resvg never reports — a family no face answers, an href no
//! asset answers, a data: URL, an asset that is not an image, a size that
//! is not the graphic's.

use std::sync::Mutex;

use resvg::tiny_skia;
use resvg::usvg;

use crate::diagnostic::Diagnostic;
use crate::library::{lock, Library, Probe};

/// The largest width or height a graphic draws at (G-7).
pub const MAX_SIDE: u32 = 8192;

/// Parses `svg` and draws it into `out`, `width`×`height` premultiplied BGRA
/// rows `stride` bytes apart. `Ok` holds the warnings, and every pixel was
/// written (transparent where nothing drew); bytes past `width × 4` in a
/// row are untouched. `Err` writes nothing.
pub fn rasterize(
    library: &Library,
    svg: &str,
    width: u32,
    height: u32,
    out: &mut [u8],
    stride: usize,
) -> Result<Vec<Diagnostic>, Diagnostic> {
    check_side("width", width)?;
    check_side("height", height)?;
    let row = width as usize * 4;
    if stride < row {
        return Err(Diagnostic::error(format!(
            "stride {stride} is under width × 4 = {row}"
        )));
    }
    let needed = height as u128 * stride as u128;
    if (out.len() as u128) < needed {
        return Err(Diagnostic::error(format!(
            "out holds {} bytes; height × stride needs {needed}",
            out.len()
        )));
    }
    let probe = Mutex::new(Probe::default());
    let options = library.options(&probe);
    let tree = usvg::Tree::from_str(svg, &options)
        .map_err(|e| Diagnostic::error(format!("the SVG did not parse: {e}")))?;
    let mut pixmap = tiny_skia::Pixmap::new(width, height)
        .ok_or_else(|| Diagnostic::error(format!("no pixmap of {width}×{height}")))?;
    resvg::render(
        &tree,
        tiny_skia::Transform::identity(),
        &mut pixmap.as_mut(),
    );
    let rgba = pixmap.data();
    for y in 0..height as usize {
        let src = &rgba[y * row..(y + 1) * row];
        let dst = &mut out[y * stride..y * stride + row];
        for (to, from) in dst.chunks_exact_mut(4).zip(src.chunks_exact(4)) {
            to[0] = from[2];
            to[1] = from[1];
            to[2] = from[0];
            to[3] = from[3];
        }
    }
    let probe = lock(&probe);
    let mut warnings = Vec::new();
    let set = library.families().join(", ");
    let mut seen: Vec<&Vec<usvg::FontFamily>> = Vec::new();
    for families in &probe.families {
        if seen.contains(&families) {
            continue;
        }
        seen.push(families);
        if families.as_slice() == [usvg::FontFamily::Named(options.font_family.clone())] {
            for message in unparsed_family_warnings(svg, &set, &options.font_family) {
                push(&mut warnings, message);
            }
        } else {
            push(&mut warnings, family_warning(families, &set));
        }
    }
    let names = library.asset_names();
    let assets = if names.is_empty() {
        "(no assets)".to_string()
    } else {
        names.join(", ")
    };
    for href in &probe.hrefs {
        push(
            &mut warnings,
            format!("<image> href \"{href}\" is not an asset; the assets are: {assets}"),
        );
    }
    if probe.data_url {
        push(
            &mut warnings,
            "<image> data: URLs are not supported; put the file in graphics/assets/ and use asset(name)"
                .to_string(),
        );
    }
    for name in &probe.bad_assets {
        push(
            &mut warnings,
            format!("asset \"{name}\" is not a PNG, JPEG, GIF, WebP or SVG(Z) image"),
        );
    }
    let size = tree.size();
    let (svg_w, svg_h) = (size.width().round() as u32, size.height().round() as u32);
    if (svg_w, svg_h) != (width, height) {
        push(
            &mut warnings,
            format!("the SVG is {svg_w}×{svg_h} but the graphic is {width}×{height}"),
        );
    }
    Ok(warnings)
}

fn check_side(name: &str, value: u32) -> Result<(), Diagnostic> {
    if value == 0 {
        Err(Diagnostic::error(format!("{name} 0 is not allowed")))
    } else if value > MAX_SIDE {
        Err(Diagnostic::error(format!(
            "{name} {value} is over the {MAX_SIDE} cap"
        )))
    } else {
        Ok(())
    }
}

/// Appends a warning unless the same text is already there.
fn push(warnings: &mut Vec<Diagnostic>, message: String) {
    if !warnings.iter().any(|w| w.message == message) {
        warnings.push(Diagnostic::warning(message));
    }
}

